      </div>` : `
      <div class="between"><span class="contract-chip">${icon('star', 10)} ${scouted ? `${Math.round(a.skill)} skill` : ''} · morale ${Math.round(a.morale)}</span><span class="pill ${weeks <= 6 ? 'red' : ''}">${status.label}</span></div>
